import logging

from app.core.config import settings

logger = logging.getLogger(__name__)


class EmailMessage:
    """Represents an email generated by the system."""

    def __init__(
        self,
        to_email: str,
        subject: str,
        html_content: str,
        plain_content: str,
        token: str | None = None,
    ):
        self.to_email = to_email
        self.subject = subject
        self.html_content = html_content
        self.plain_content = plain_content
        self.token = token  # Retained in memory only for testing verification flows


class EmailService:
    """
    Provider-independent email delivery service.
    In development and test environments, stores messages in an in-memory test mailbox
    and supports optional SMTP forwarding.
    """

    def __init__(self):
        self._sent_mailbox: list[EmailMessage] = []

    def clear_mailbox(self) -> None:
        """Clears captured messages (used in testing)."""
        self._sent_mailbox.clear()

    def get_sent_messages(self) -> list[EmailMessage]:
        """Returns captured messages for assertion in tests."""
        return list(self._sent_mailbox)

    def get_latest_token_for(self, email: str) -> str | None:
        """Helper for test suites to extract the latest generated token."""
        for msg in reversed(self._sent_mailbox):
            if msg.to_email.lower() == email.lower() and msg.token:
                return msg.token
        return None

    def _deliver(self, message: EmailMessage) -> bool:
        """
        Delivers an email message.
        Always records to in-memory mailbox (for testing and audit inspection).
        When settings.SMTP_ENABLED is True, dispatches via standard SMTP.
        """
        self._sent_mailbox.append(message)

        if not settings.SMTP_ENABLED:
            logger.info(
                "Email recorded in test mailbox for %s: %s", message.to_email, message.subject
            )
            return True

        try:
            import smtplib
            from email.mime.multipart import MIMEMultipart
            from email.mime.text import MIMEText

            msg = MIMEMultipart("alternative")
            msg["Subject"] = message.subject
            msg["From"] = f"{settings.EMAILS_FROM_NAME} <{settings.EMAILS_FROM_EMAIL}>"
            msg["To"] = message.to_email

            msg.attach(MIMEText(message.plain_content, "plain"))
            msg.attach(MIMEText(message.html_content, "html"))

            with smtplib.SMTP(settings.SMTP_HOST, settings.SMTP_PORT, timeout=10) as server:
                if settings.SMTP_TLS:
                    server.starttls()
                if settings.SMTP_USER and settings.SMTP_PASSWORD:
                    server.login(settings.SMTP_USER, settings.SMTP_PASSWORD)
                server.send_message(msg)

            logger.info("Email dispatched via SMTP to %s: %s", message.to_email, message.subject)
            return True
        except Exception as err:
            logger.error("Failed SMTP delivery to %s: %s", message.to_email, str(err))
            return False

    def send_verification_email(
        self,
        to_email: str,
        full_name: str,
        raw_token: str,
    ) -> bool:
        """Sends an account email verification message."""
        verification_url = f"{settings.FRONTEND_URL}/verify-email?token={raw_token}"
        subject = f"Verify your email — {settings.APP_NAME}"

        plain_text = (
            f"Hello {full_name},\n\n"
            f"Welcome to {settings.APP_NAME}. Please verify your email address by opening the following link:\n"
            f"{verification_url}\n\n"
            f"This link expires in {settings.EMAIL_VERIFICATION_TOKEN_EXPIRE_HOURS} hours.\n\n"
            f"If you did not create an account, please disregard this email."
        )

        html_text = f"""
        <!DOCTYPE html>
        <html>
        <body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.6; color: #1e293b; max-width: 600px; margin: 0 auto; padding: 24px;">
            <div style="background-color: #0f172a; padding: 20px; border-radius: 12px 12px 0 0; text-align: center;">
                <h1 style="color: #ffffff; margin: 0; font-size: 20px;">{settings.APP_NAME}</h1>
            </div>
            <div style="background-color: #ffffff; padding: 32px; border: 1px solid #e2e8f0; border-top: none; border-radius: 0 0 12px 12px;">
                <h2 style="font-size: 18px; color: #0f172a; margin-top: 0;">Verify your email address</h2>
                <p>Hello {full_name},</p>
                <p>Thank you for registering with {settings.APP_NAME}. Click the button below to confirm your email and activate your account:</p>
                <div style="margin: 32px 0; text-align: center;">
                    <a href="{verification_url}" style="background-color: #059669; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 8px; font-weight: 600; display: inline-block;">Verify Email Address</a>
                </div>
                <p style="font-size: 12px; color: #64748b;">Or copy and paste this link into your browser:<br/><span style="color: #059669;">{verification_url}</span></p>
                <p style="font-size: 12px; color: #94a3b8; margin-top: 32px; border-top: 1px solid #e2e8f0; padding-top: 16px;">This link expires in {settings.EMAIL_VERIFICATION_TOKEN_EXPIRE_HOURS} hours. If you did not sign up, please ignore this email.</p>
            </div>
        </body>
        </html>
        """

        message = EmailMessage(
            to_email=to_email,
            subject=subject,
            html_content=html_text,
            plain_content=plain_text,
            token=raw_token,
        )
        return self._deliver(message)

